{"implementation":"def solve(case):
    """Compute a conservative effect-preserving pruning plan for a node tree.

    The input is expected to contain a list of nodes, each with id, parent,
    symbol, removable, and utility fields, plus required_symbols.  A removable
    node may be pruned only if doing so does not remove any non-removable node
    and leaves at least one occurrence of every required symbol in the retained
    tree.  Pruning a node also removes its descendants.
    """
    payload = case.get("payload", case) if isinstance(case, dict) else {}
    nodes = list(payload.get("nodes", []))
    required_symbols = set(payload.get("required_symbols", []))

    by_id = {node.get("id"): node for node in nodes}
    children = {node.get("id"): [] for node in nodes}
    roots = []
    for node in nodes:
        node_id = node.get("id")
        parent = node.get("parent")
        if parent is None or parent not in children:
            roots.append(node_id)
        else:
            children[parent].append(node_id)

    descendants_cache = {}

    def subtree_ids(node_id):
        if node_id in descendants_cache:
            return descendants_cache[node_id]
        result = [node_id]
        stack = list(children.get(node_id, ()))
        while stack:
            current = stack.pop()
            result.append(current)
            stack.extend(children.get(current, ()))
        descendants_cache[node_id] = result
        return result

    retained = set(by_id)
    removed_roots = []

    def current_symbol_counts():
        counts = {}
        for node_id in retained:
            symbol = by_id[node_id].get("symbol")
            counts[symbol] = counts.get(symbol, 0) + 1
        return counts

    def can_remove(node_id):
        if node_id not in retained:
            return False
        node = by_id[node_id]
        if not node.get("removable", False):
            return False
        sub = [sid for sid in subtree_ids(node_id) if sid in retained]
        for sid in sub:
            if not by_id[sid].get("removable", False):
                return False
        counts = current_symbol_counts()
        for sid in sub:
            sym = by_id[sid].get("symbol")
            counts[sym] = counts.get(sym, 0) - 1
        for sym in required_symbols:
            if counts.get(sym, 0) <= 0:
                return False
        return True

    removable_ids = [node.get("id") for node in nodes if node.get("removable", False)]

    def removal_gain(node_id):
        return sum(float(by_id[sid].get("utility", 0.0)) for sid in subtree_ids(node_id) if sid in retained)

    # Prefer pruning larger/higher-utility removable subtrees first; ties are
    # deterministic and favor deeper nodes only after utility and size match.
    candidates = sorted(
        removable_ids,
        key=lambda nid: (
            -removal_gain(nid),
            -len(subtree_ids(nid)),
            -int(by_id[nid].get("depth", 0) or 0),
            str(nid),
        ),
    )

    changed = True
    while changed:
        changed = False
        for node_id in candidates:
            if can_remove(node_id):
                sub = set(subtree_ids(node_id)) & retained
                retained.difference_update(sub)
                removed_roots.append(node_id)
                changed = True

    kept_nodes = [node.get("id") for node in nodes if node.get("id") in retained]
    removed_nodes = [node.get("id") for node in nodes if node.get("id") not in retained]
    kept_utility = sum(float(node.get("utility", 0.0)) for node in nodes if node.get("id") in retained)
    removed_utility = sum(float(node.get("utility", 0.0)) for node in nodes if node.get("id") not in retained)

    return {
        "kept_nodes": kept_nodes,
        "removed_nodes": removed_nodes,
        "removed_roots": removed_roots,
        "kept_utility": kept_utility,
        "removed_utility": removed_utility,
    }
"}
